tool_input.command:
python -c "
import hopsworks
project = hopsworks.login()
ds = project.get_dataset_api()

# List training datasets
try:
    files = ds.list('Training_Datasets')
    for f in files:
        print(f)
except Exception as e:
    print('Error:', e)
    # Try alternative
    try:
        items = ds.list('Training_Datasets', list_content=True)
        for i in items:
            print(i)
    except Exception as e2:
        print('Error2:', e2)
" 2>&1 | grep -v "^2026"
